import { defineConfig } from "@neon/config/v1";

export default defineConfig({
  // Neon Auth (Managed Better Auth) - Replace Firebase Auth
  auth: true,

  // Neon Functions - Long-running serverless functions
  functions: {
    // Main API function - handles REST API
    api: {
      name: "Instagram Clone API",
      source: "src/index.ts",
      externalPackages: ["bcrypt"],
      // Environment variables (secrets) - declared here, values from .env at deploy
      env: {
        // Better Auth secrets (generated by `neon auth secret`)
        BETTER_AUTH_SECRET: process.env.BETTER_AUTH_SECRET || "dev-secret-change-in-production",
        BETTER_AUTH_URL: process.env.BETTER_AUTH_URL || "http://localhost:3000",
        // Email provider (Resend, SendGrid, etc.) - optional for local dev
        RESEND_API_KEY: process.env.RESEND_API_KEY || "re_dummy_local_dev",
        // CORS
        CORS_ORIGIN: process.env.CORS_ORIGIN || "http://localhost:3000,http://localhost:8081",
        // Logging
        LOG_LEVEL: process.env.LOG_LEVEL || "info",
      },
    },
    // WebSocket function for real-time chat/calls (separate for scaling)
    ws: {
      name: "WebSocket Server",
      source: "src/websocket/index.ts",
      externalPackages: ["bcrypt"],
      env: {
        BETTER_AUTH_SECRET: process.env.BETTER_AUTH_SECRET || "dev-secret-change-in-production",
        CORS_ORIGIN: process.env.CORS_ORIGIN || "http://localhost:3000,http://localhost:8081",
        LOG_LEVEL: process.env.LOG_LEVEL || "info",
      },
    },
  },

  // Neon Object Storage (S3-compatible) - Replace Firebase Storage
  buckets: {
    // Private bucket for user uploads (avatars, posts, stories, reels)
    uploads: {
      access: "private",
    },
    // Public bucket for CDN-served content (thumbnails, processed media)
    public: {
      access: "public_read",
    },
  },

  // Neon Realtime - Live SQL queries for chat messages, notifications, presence
  preview: {
    realtime: true,
  },

  // Branch policy
  branch: (branch) => {
    if (branch.isDefault) {
      // Main branch: production-like settings
      return {
        functions: {
          api: { runtime: "nodejs24" },
          ws: { runtime: "nodejs24" },
        },
      };
    }
    if (!branch.exists) {
      // Preview branches: auto-expire after 7 days
      return {
        ttl: "7d",
        functions: {
          api: { runtime: "nodejs24" },
          ws: { runtime: "nodejs24" },
        },
      };
    }
    return {};
  },
});